class ArcAnalyzer:
    """Analyze ARC tasks and compare transformations"""

    def __init__(self, workspace):
        self.workspace = workspace

    def load_input_grid(self, filepath):
        """Load a JSON input grid"""
        with open(os.path.join(self.workspace, filepath), 'r') as f:
            content = json.load(f)
        return content.get('grid', [])

    def load_parsed_grid(self, filepath):
        """Load a space-separated grid file as JSON"""
        with open(os.path.join(self.workspace, filepath), 'r') as f:
            content = f.read().strip()
        lines = content.split('\n')
        return [[int(x) for x in line.split()] for line in lines]

    def grid_to_json(self, grid):
        """Convert nested list to pretty JSON"""
        return "\t".join("\t".join(str(cell) for cell in row) for row in grid)

    def print_grid(self, grid, title=""):
        """Print a grid nicely"""
        if title:
            print(f"\n=== {title} ({len(grid)}x{len(grid[0]) if grid else 0}) ===")
        print(self.grid_to_json(grid))

    def find_objects(self, grid, background=3):
        """Find non-background objects in the grid"""
        objects = []
        visited = set()
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] != background and (r, c) not in visited:
                    # Find connected component
                    obj = []
                    stack = [(r, c)]
                    while stack:
                        cr, cc = stack.pop()
                        key = (cr, cc)
                        if key not in visited:
                            visited.add(key)
                            obj.append((cr, cc, grid[cr][cc]))
                            # Check neighbors
                            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                                nr, nc = cr + dr, cc + dc
                                if 0 <= nr < rows and 0 <= nc < cols:
                                    if grid[nr][nc] != background and (nr, nc) not in visited:
                                        stack.append((nr, nc))
                    objects.append({
                        'cells': obj,
                        'size': len(obj),
                        'colors': set(c for _, _, c in obj)
                    })
        return objects

    def transform_rotate_90(self, grid):
        """Rotate grid 90 degrees clockwise"""
        return [list(reversed([grid[r][c] for r in range(len(grid))])) 
                for c in range(len(grid[0]))]

    def transform_rotate_180(self, grid):
        """Rotate grid 180 degrees"""
        return [list(reversed(row[::-1])) for row in reversed(grid)]

    def transform_flip_h(self, grid):
        """Flip grid horizontally"""
        return [row[::-1] for row in grid]

    def transform_flip_v(self, grid):
        """Flip grid vertically"""
        return grid[::-1]

    def transform_identity(self, grid):
        """Return grid unchanged"""
        return [row[:] for row in grid]

    def compare_grids(self, grid1, grid2):
        """Compare two grids and return differences"""
        rows1, cols1 = len(grid1), len(grid1[0]) if grid1 else 0
        rows2, cols2 = len(grid2), len(grid2[0]) if grid2 else 0

        if rows1 != rows2 or cols1 != cols2:
            return {
                'size_mismatch': True,
                'dims1': (rows1, cols1),
                'dims2': (rows2, cols2)
            }

        diffs = []
        max_diff = 0
        for r in range(rows1):
            for c in range(cols1):
                if grid1[r][c] != grid2[r][c]:
                    diffs.append((r, c, grid1[r][c], grid2[r][c]))
                    max_diff += 1

        return {
            'size_mismatch': False,
            'diff_count': max_diff,
            'diff_percentage': max_diff / (rows1 * cols1) if rows1 * cols1 > 0 else 0,
            'differences': diffs[:50]  # First 50 differences
        }

