import json
import os

class ArcTaskAnalyzer:
    """
    Comprehensive ARClab Task Analyzer

    Analyzes ARC (Abstraction and Reasoning Corpus) puzzle tasks,
    applies transformations, compares solutions, and provides insights.
    """

    def __init__(self, workspace_dir):
        self.workspace = workspace_dir
        self.tasks_dir = os.path.join(workspace_dir, 'tasks')

    def load_space_separated_file(self, filepath):
        """Load a space-separated grid file"""
        with open(filepath, 'r') as f:
            content = f.read().strip()
        lines = content.split('\n')
        return [[int(x) for x in line.split()] for line in lines]

    def load_json_grid(self, filepath):
        """Load a JSON grid file"""
        with open(filepath, 'r') as f:
            data = json.load(f)
        return data.get('grid', [])

    def visualize_grid(self, grid):
        """Print a grid with dimensions"""
        if not grid:
            return "Empty grid"
        height = len(grid)
        width = len(grid[0])
        lines = []
        for row in grid:
            lines.append('\t'.join(str(c) for c in row))
        return f"[{height}x{width}]\n" + '\n'.join(lines)

    def find_objects(self, grid, background=3):
        """Find all non-background objects in the grid"""
        visited = set()
        objects = []
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] != background and (r, c) not in visited:
                    # Find connected component
                    cells = []
                    stack = [(r, c)]
                    while stack:
                        cr, cc = stack.pop()
                        if (cr, cc) not in visited:
                            visited.add((cr, cc))
                            cells.append((cr, cc, grid[cr][cc]))
                            # Check 4-neighbors
                            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                                nr, nc = cr + dr, cc + dc
                                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                                    if grid[nr][nc] != background and (nr, nc) not in visited:
                                        stack.append((nr, nc))
                    objects.append({
                        'size': len(cells),
                        'cells': cells,
                        'colors': sorted(list(set(c for _, _, c in cells)))
                    })
        return objects

    def get_color_histogram(self, grid):
        """Get frequency of each color in grid"""
        colors = {}
        for row in grid:
            for cell in row:
                colors[cell] = colors.get(cell, 0) + 1
        return sorted(colors.items(), key=lambda x: -x[1])

    def apply_transformation(self, grid, transform_name):
        """Apply geometric transformation to grid"""
        if transform_name == 'identity':
            return [row[:] for row in grid]
        elif transform_name == 'rotate_90':
            return [list(reversed([grid[r][c] for r in range(len(grid))])) 
                    for c in range(len(grid[0]))]
        elif transform_name == 'rotate_180':
            return [list(reversed(row)) for row in reversed(grid)]
        elif transform_name == 'rotate_270':
            return [list(reversed([grid[r][c] for r in range(len(grid))])) 
                    for c in range(len(grid[0]))]
        elif transform_name == 'flip_h':
            return [row[::-1] for row in grid]
        elif transform_name == 'flip_v':
            return [row[:] for row in reversed(grid)]
        elif transform_name == 'transpose':
            return [[grid[r][c] for r in range(len(grid))] for c in range(len(grid[0]))]
        else:
            raise ValueError(f"Unknown transform: {transform_name}")

    def compare_with_correct(self, solution_grid, correct_grid):
        """Compare a solution against the correct answer"""
        s_rows, s_cols = len(solution_grid), len(solution_grid[0])
        c_rows, c_cols = len(correct_grid), len(correct_grid[0])

        if s_rows != c_rows or s_cols != c_cols:
            return {
                'correct': False,
                'status': 'size_mismatch',
                'solution_dims': (s_rows, s_cols),
                'expected_dims': (c_rows, c_cols)
            }

        diffs = []
        diff_count = 0
        for r in range(s_rows):
            for c in range(s_cols):
                if solution_grid[r][c] != correct_grid[r][c]:
                    diffs.append((r, c, solution_grid[r][c], correct_grid[r][c]))
                    diff_count += 1

        accuracy = (s_rows * s_cols - diff_count) / (s_rows * s_cols) * 100

        return {
            'correct': diff_count == 0,
            'status': 'size_match' if s_rows == c_rows else 'size_mismatch',
            'diff_count': diff_count,
            'total_cells': s_rows * s_cols,
            'accuracy': round(accuracy, 2),
            'sample_differences': diffs[:20]
        }

