import json
import os

class ArcTaskAnalyzer:
    """
    ARC (Abstraction and Reasoning Corpus) Task Analyzer

    This analyzer can:
    - Load task inputs and ground truth answers
    - Compare solutions against references
    - Identify transformation patterns
    - Extract objects and analyze grid structure
    """

    def __init__(self, workspace_dir):
        self.workspace = workspace_dir
        self.tasks_dir = os.path.join(workspace_dir, 'tasks')

    def __repr__(self):
        return f"ArcTaskAnalyzer(workspace={self.workspace})"

    def load_space_separated_grid(self, filepath):
        """Load a space-separated grid file into nested list"""
        with open(filepath, 'r') as f:
            content = f.read()
        lines = content.strip().split('\n')
        return [[int(x) for x in line.split()] for line in lines]

    def load_json_grid(self, filepath):
        """Load a JSON grid file"""
        with open(filepath, 'r') as f:
            return json.load(f)

    def save_grid_to_json(self, grid, filepath):
        """Save a grid to a JSON file"""
        with open(filepath, 'w') as f:
            json.dump(grid, f, indent=2)

    def save_grid_space_separated(self, grid, filepath):
        """Save a grid as space-separated text"""
        with open(filepath, 'w') as f:
            for row in grid:
                f.write(' '.join(str(cell) for cell in row) + '\n')

    def visualize_grid(self, grid, max_rows=10, max_cols=20):
        """Print a grid with truncation if too large"""
        if not grid:
            return "Empty grid"

        rows_to_show = min(len(grid), max_rows)
        cols_to_show = min(len(grid[0]), max_cols)

        lines = []
        for row in grid[:rows_to_show]:
            lines.append('\t'.join(str(c) for c in row[:cols_to_show]))

        if len(grid) > max_rows:
            lines.append(f"... ({len(grid)} total rows)")
        if len(grid[0]) > max_cols:
            lines.append(f"... ({len(grid[0])} total cols)")

        return '\n'.join(lines)

    def get_background(self, grid):
        """Get the background color (most frequent value)"""
        colors = {}
        for row in grid:
            for cell in row:
                colors[cell] = colors.get(cell, 0) + 1
        return max(colors.keys(), key=lambda x: colors[x])

    def find_objects(self, grid, background=None):
        """Find all connected non-background objects in grid"""
        if background is None:
            background = self.get_background(grid)

        visited = set()
        objects = []

        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] != background and (r, c) not in visited:
                    # BFS to find connected component
                    cells = []
                    stack = [(r, c, grid[r][c])]
                    while stack:
                        cr, cc, color = stack.pop()
                        if (cr, cc) not in visited:
                            visited.add((cr, cc))
                            cells.append((cr, cc, color))
                            # Check 4-neighbors
                            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                                nr, nc = cr + dr, cc + dc
                                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                                    if grid[nr][nc] != background and (nr, nc) not in visited:
                                        stack.append((nr, nc, grid[nr][nc]))

                            # Replace list with tuple for consistency
                            cells = [(cr, cc, color) for cr, cc, color in cells]

                    objects.append({
                        'cells': [(cr, cc, color) for cr, cc, color in cells],
                        'size': len(cells),
                        'colors': sorted(set(c for _, _, c in cells)),
                        'bounds': (min(cr for cr, _, _ in cells), 
                                 min(cc for _, cc, _ in cells),
                                 max(cr for cr, _, _ in cells),
                                 max(cc for _, cc, _ in cells))
                    })

        return objects

    def get_color_histogram(self, grid):
        """Get frequency of each color in the grid"""
        colors = {}
        total = 0
        for row in grid:
            for cell in row:
